import{B as e,Q as t,s as n,z as r}from"./chunks/framework.hue4hZNP.js";import"./chunks/admin-ai-settings.C0sOEI-f.js";var i=JSON.parse(`{"title":"Configure AI Providers","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configure-ai-providers.md","filePath":"guide/configure-ai-providers.md"}`),a={name:`guide/configure-ai-providers.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="configure-ai-providers" tabindex="-1">Configure AI Providers <a class="header-anchor" href="#configure-ai-providers" aria-label="Permalink to &quot;Configure AI Providers&quot;">​</a></h1><p>An admin&#39;s guide to turning on AI narration — the feature that generates live commentary for every segment your promotion runs. Requires the ADMIN role.</p><p><strong>What AI narration does:</strong> when a show runs, each segment gets play-by-play commentary, wrestler promos get voice, and show recaps are written for you. Without a provider, shows still run — you just don&#39;t get the narration.</p><hr><h2 id="step-1-—-pick-a-provider-and-get-a-key" tabindex="-1">Step 1 — Pick a provider and get a key <a class="header-anchor" href="#step-1-—-pick-a-provider-and-get-a-key" aria-label="Permalink to &quot;Step 1 — Pick a provider and get a key&quot;">​</a></h2><p>The game supports <strong>OpenAI</strong>, <strong>Claude (Anthropic)</strong>, <strong>Gemini</strong>, <strong>Pollinations</strong>, and <strong>Ollama</strong> (local, no key). You only need ONE enabled.</p><blockquote><p>💡 <strong>Costs:</strong> Gemini&#39;s free tier has daily request limits that are plenty for a single promotion. OpenAI and Claude are paid per request. Pollinations offers free tiers. Ollama runs on your own machine — no key, no network, just a slower local model.</p></blockquote><p>To get a Gemini key (the usual starting point):</p><ol><li>Go to <a href="https://aistudio.google.com/" target="_blank" rel="noreferrer">Google AI Studio</a> and sign in with a Google account.</li><li>Click <strong>Get API key</strong> → <strong>Create API key</strong> (a new Google Cloud project is created for you automatically).</li><li>Copy the key (starts with <code>AIza…</code>). Treat it like a password — anyone who has it can spend your quota.</li></ol><hr><h2 id="step-2-—-configure-it-in-ai-settings" tabindex="-1">Step 2 — Configure it in AI Settings <a class="header-anchor" href="#step-2-—-configure-it-in-ai-settings" aria-label="Permalink to &quot;Step 2 — Configure it in AI Settings&quot;">​</a></h2><p>In <strong>Admin → AI Settings</strong> you&#39;ll find collapsible sections — one common section on top, then one per provider:</p><ol><li>Find the provider section you have a key for (e.g. <strong>Gemini Settings</strong>) and expand it.</li><li>Tick <strong>Enabled</strong>.</li><li>Paste the key into <strong>API Key</strong>. Fields save as you edit — a notification confirms each change.</li><li>Leave <strong>API URL</strong> and <strong>Model Name</strong> at their defaults unless your provider documents otherwise.</li><li>If you enable more than one provider, leave <strong>Auto Select Provider</strong> ticked in the common section and the game picks the first available one. Untick it to pin a specific provider.</li></ol><p><img src="/screenshots/admin-ai-settings.png" alt="AI Settings"></p><p><strong>Provider notes:</strong></p><ul><li><strong>Ollama</strong> needs no key — set the <strong>Base URL</strong> of your local server (default <code>http://localhost:11434</code>) and the <strong>Model</strong> tag to pull (default <code>llama3.2:1b</code>). Environment variables <code>OLLAMA_BASE_URL</code> and <code>OLLAMA_MODEL</code> take priority over the UI values.</li><li><strong>Timeout (seconds)</strong> in the common section caps how long narration requests wait. Raise it for slow local models.</li><li>The OpenAI section exposes extra knobs (default/premium/image models, max tokens, temperature) used by features that generate art as well as narration.</li></ul><p><strong>Keys are stored in the database</strong> and survive restarts. If you run the app in Docker, you can bootstrap keys with environment variables instead (<code>AI_GEMINI_API_KEY</code>, <code>AI_OPENAI_API_KEY</code>, <code>AI_CLAUDE_API_KEY</code>) — a value set in the UI always wins over the environment afterward.</p><hr><h2 id="step-3-—-verify-narration-works" tabindex="-1">Step 3 — Verify narration works <a class="header-anchor" href="#step-3-—-verify-narration-works" aria-label="Permalink to &quot;Step 3 — Verify narration works&quot;">​</a></h2><p>Run any show with a pending segment (see <a href="./schedule-a-show.html">Schedule a Show</a>) and open its detail page after adjudication — each segment should show generated commentary.</p><p>If narration is missing:</p><ol><li>Check the provider is <strong>Enabled</strong> and the key was accepted.</li><li>Check the <strong>Timeout</strong> — a local Ollama model on first load may need more time while it pulls the model.</li><li>Check the application logs for provider errors (wrong key, quota exhausted).</li></ol><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./admin-getting-started.html">Admin Getting Started</a> — the wider admin setup, including content expansions.</li><li><a href="./ai-features.html">AI Features overview</a> — everything the AI layer powers: commentator personas, show recaps, and more.</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};